UPDATE chapter_creation_idempotency
   SET chapter_id = NULL
 WHERE chapter_id = #{chapterId}

mapper.select:
SELECT 
  FROM chapters
 WHERE story_version_id = #{storyVersionId}
 ORDER BY order_index ASC, id ASC
 LIMIT #{limit}

SELECT 
  FROM chapters
 WHERE story_version_id = #{storyVersionId}
   AND (order_index > #{orderIndex}
        OR (order_index = #{orderIndex} AND id > #{id}))
 ORDER BY order_index ASC, id ASC
 LIMIT #{limit}

SELECT EXISTS (
    SELECT 1
      FROM chapters
     WHERE story_version_id = #{storyVersionId}
       AND order_index = #{orderIndex}
)

SELECT COALESCE(MAX(order_index), -1)
  FROM chapters
 WHERE story_version_id = #{storyVersionId}
